3 Helpers

def add_intercept(x):
    return np.column_stack([np.ones(x.shape[0]), x])


def build_designs(x_endog, x_exog, z_excluded):
    x_rhs = np.column_stack([x_endog, x_exog]) if x_exog.shape[1] &gt; 0 else x_endog
    z_rhs = (
        np.column_stack([x_exog, z_excluded]) if x_exog.shape[1] &gt; 0 else z_excluded
    )
    return add_intercept(x_rhs), add_intercept(z_rhs)


def twosls_via_lstsq(x_endog, x_exog, z_excluded, y):
    x_design, z_design = build_designs(x_endog, x_exog, z_excluded)
    pi_hat, *_ = np.linalg.lstsq(z_design, x_endog, rcond=None)
    x_endog_hat = z_design @ pi_hat
    x_hat_rhs = (
        np.column_stack([x_endog_hat, x_exog]) if x_exog.shape[1] &gt; 0 else x_endog_hat
    )
    x_hat_design = add_intercept(x_hat_rhs)
    theta_hat, *_ = np.linalg.lstsq(x_hat_design, y, rcond=None)
    return theta_hat


def twosls_via_projection_formula(x_endog, x_exog, z_excluded, y):
    x_design, z_design = build_designs(x_endog, x_exog, z_excluded)
    ztz_inv = np.linalg.inv(z_design.T @ z_design)
    pz = z_design @ ztz_inv @ z_design.T
    return np.linalg.solve(x_design.T @ pz @ x_design, x_design.T @ pz @ y)

2 Helpers

def read_numeric_data(path, columns=None):
    frame = pl.read_csv(path, null_values=["", "NA", "NaN"])
    candidate_columns = columns or [name for name in frame.columns if name != "rownames"]

    numeric = frame.select(
        pl.col(name).cast(pl.Float64, strict=False).alias(name)
        for name in candidate_columns
    )
    if columns is None:
        columns = [
            name
            for name in numeric.columns
            if numeric.select(pl.col(name).is_not_null().any()).item()
        ]

    return columns, numeric.select(columns).drop_nulls().to_numpy()


def standardize(x):
    return (x - x.mean(axis=0, keepdims=True)) / x.std(axis=0, ddof=1, keepdims=True)


def pca_loadings_from_data(x, n_factors):
    z = standardize(x)
    _, singular_values, vt = np.linalg.svd(z, full_matrices=False)
    return vt[:n_factors].T * singular_values[:n_factors] / np.sqrt(z.shape[0] - 1)


def loadings_from_correlation(corr, n_factors):
    eigenvalues, eigenvectors = np.linalg.eigh(corr)
    order = np.argsort(eigenvalues)[::-1]
    eigenvalues = eigenvalues[order]
    eigenvectors = eigenvectors[:, order]
    return eigenvectors[:, :n_factors] * np.sqrt(eigenvalues[:n_factors])


def normalized_columns(x):
    return x / np.linalg.norm(x, axis=0, keepdims=True)


def max_abs_column_matches(estimate, truth):
    score = np.abs(normalized_columns(estimate).T @ normalized_columns(truth))
    return score.max(axis=1)


def loading_heatmaps(left, right, row_labels, titles, figsize=(13, 6.5)):
    fig, axes = plt.subplots(1, 2, figsize=figsize, constrained_layout=True)
    limit = max(np.abs(left).max(), np.abs(right).max())
    image = None

    for ax, values, title in zip(axes, [left, right], titles):
        image = ax.imshow(values, cmap="coolwarm", vmin=-limit, vmax=limit, aspect="auto")
        ax.set_title(title)
        ax.set_xticks(range(values.shape[1]), [f"F{j + 1}" for j in range(values.shape[1])])
        ax.set_yticks(range(len(row_labels)), row_labels)
        ax.tick_params(axis="y", labelsize=9)

    fig.colorbar(image, ax=axes, shrink=0.85, label="loading")
    plt.show()

3 Moment Functions
For linear IV, the sample moment vector is just
gbar(theta) = Z' (y - X theta) / n.
That is enough to drive both a scalar GMM criterion and a least-squares residual system.

def sample_moments(theta, x, y, z):
    resid = y - x @ theta
    return z.T @ resid / x.shape[0]

def moment_jacobian(theta, x, y, z):
    del theta, y
    return -(z.T @ x) / x.shape[0]

def gmm_criterion(theta, x, y, z, weight):
    g = sample_moments(theta, x, y, z)
    return float(g @ weight @ g)

def gmm_gradient(theta, x, y, z, weight):
    g = sample_moments(theta, x, y, z)
    G = moment_jacobian(theta, x, y, z)
    return 2.0 * G.T @ (weight @ g)

def whitened_residual(theta, x, y, z, weight_root):
    return weight_root @ sample_moments(theta, x, y, z)

def whitened_jacobian(theta, x, y, z, weight_root):
    return weight_root @ moment_jacobian(theta, x, y, z)

def closed_form_linear_gmm(x, y, z, weight):
    zx = z.T @ x
    zy = z.T @ y
    return np.linalg.solve(zx.T @ weight @ zx, zx.T @ weight @ zy)

def omega_hat(theta, x, y, z):
    resid = y - x @ theta
    gi = z * resid[:, None]
    return gi.T @ gi / x.shape[0]

def make_weight_root(weight):
    ridge = 1e-10 * np.eye(weight.shape[0])
    return np.linalg.cholesky(weight + ridge).T

The two optimizer interfaces line up naturally with GMM:

Optimizers.minimize_bfgs wants a scalar criterion and its gradient
Optimizers.minimize_gauss_newton_ls wants a residual vector and its Jacobian

If we whiten the moments as r(theta) = W^{1/2} gbar(theta), then minimizing ||r(theta)||^2 is exactly the same point-estimate problem as minimizing the usual quadratic GMM criterion.

